const items = $input.all();
const src = (items[0] && items[0].json) || {};
const rawMsg = typeof src.message === 'string' ? src.message : '';
const rawId = typeof src.request_id === 'string' ? src.request_id : '';
return [{ json: {
  message: rawMsg.trim(),
  request_id: rawId.trim() || 'demo-unknown',
  had_input: items.length > 0 && rawMsg.trim().length > 0
}}];

const d = $input.first().json;
if (!d.message) {
  return [{ json: { ...d, valid: false, error: 'EMPTY_MESSAGE: message is missing or empty after trimming' } }];
}
if (d.message.length > 2000) {
  return [{ json: { ...d, valid: false, error: 'MESSAGE_TOO_LONG: limit is 2000 characters' } }];
}
return [{ json: { ...d, valid: true, error: null } }];

const d = $input.first().json;
const base = { ...d, category: 'unknown', intent: 'invalid_input', priority: 'low', needs_human_review: true, summary: '', suggested_actions: [] };
if (!d.valid) return [{ json: base }];
const text = d.message.toLowerCase();
const hasAny = (...words) => words.some((w) => text.includes(w));
const CATEGORY_RULES = [
  ['sales', ['price', 'quote', 'proposal', 'discount', 'lead', 'deal', 'pipeline', 'order', 'سعر', 'عرض سعر', 'عميل محتمل', 'صفقة']],
  ['marketing', ['campaign', 'ad', 'seo', 'content', 'brand', 'social media', 'launch', 'حملة', 'إعلان', 'تسويق', 'محتوى']],
  ['operations', ['task', 'organize', 'schedule', 'process', 'inventory', 'operations', 'workflow', 'مهمة', 'مهام', 'تنظيم', 'مخزون', 'تشغيل']],
  ['customer_support', ['support', 'help', 'issue', 'complaint', 'refund request', 'ticket', 'دعم', 'مساعدة', 'مشكلة', 'شكوى']],
  ['finance', ['invoice', 'payment', 'billing', 'budget', 'expense', 'refund', 'salary', 'فاتورة', 'دفع', 'ميزانية', 'مصروف', 'استرداد']]
];
const EXTERNAL_VERBS = ['send', 'post', 'publish', 'email', 'message ', 'notify', 'book', 'schedule a call', 'pay', 'charge', 'refund ', 'delete', 'remove', 'cancel ', 'call ', 'أرسل', 'احجز', 'ادفع', 'احذف', 'اتصل'];
const URGENT_WORDS = ['urgent', 'asap', 'immediately', 'critical', 'outage', 'crisis', 'emergency', 'عاجل', 'فوري', 'طارئ'];
let category = 'general';
for (const [cat, words] of CATEGORY_RULES) {
  if (hasAny(...words)) { category = cat; break; }
}
const wantsExternal = hasAny(...EXTERNAL_VERBS);
const wordCount = d.message.trim().split(/\s+/).filter(Boolean).length;
const matchedKnown = category !== 'general';
let intent = 'request_info';
if (wantsExternal) intent = 'request_action';
else if (hasAny('complaint', 'angry', 'terrible', 'worst', 'شكوى', 'غاضب')) intent = 'complaint';
else if (!matchedKnown && wordCount < 4) intent = 'vague';
let priority = 'normal';
if (hasAny(...URGENT_WORDS)) priority = 'high';
else if (category === 'finance' && hasAny('fraud', 'loss', 'refund', 'overdue', 'احتيال', 'خسارة', 'متأخر')) priority = 'high';
else if (intent === 'vague' || intent === 'invalid_input') priority = 'low';
const needs_human_review = intent === 'vague' || intent === 'invalid_input' || wantsExternal;
if (intent === 'vague') category = 'unknown';
const summary = d.message.length > 120 ? d.message.slice(0, 120) + '…' : d.message;
const SUGGESTIONS = {
  sales: ['draft a quote reply', 'create a follow-up task', 'escalate hot lead to owner'],
  marketing: ['draft a content outline', 'create a campaign task', 'escalate to owner'],
  operations: ['break the request into tasks', 'create a task list', 'escalate to owner'],
  customer_support: ['draft an acknowledgement reply', 'open a support ticket draft', 'escalate to owner'],
  finance: ['prepare the figures for review', 'create a review task', 'escalate to owner'],
  general: ['draft a reply', 'create a task', 'escalate to owner'],
  unknown: ['ask a clarifying question', 'escalate to owner']
};
return [{ json: { ...d, category, intent, priority, needs_human_review, summary, suggested_actions: (SUGGESTIONS[category] || SUGGESTIONS.unknown).slice(0, 3) } }];

const d = $input.first().json;
let status = 'ok';
if (!d.valid) status = 'rejected';
else if (d.needs_human_review) status = 'needs_review';
let reply = '';
if (!d.valid) {
  reply = 'I could not process this request: ' + (d.error || 'invalid input') + '. Please send a non-empty message.';
} else if (d.intent === 'vague') {
  reply = 'Your message is a bit unclear. Could you describe what you need (e.g. sales, support, or organizing tasks)? No action was taken.';
} else if (d.intent === 'request_action') {
  reply = 'Understood (' + d.category + '). I did not execute any external action. Suggested next step: ' + (d.suggested_actions[0] || 'review manually') + '. A human should approve before anything is sent, booked, or changed.';
} else {
  reply = 'Classified as ' + d.category + ' (' + d.intent + ', ' + d.priority + ' priority). Summary: ' + d.summary;
}
return [{ json: {
  request_id: d.request_id,
  status,
  category: d.category,
  intent: d.intent,
  priority: d.priority,
  summary: d.summary,
  suggested_actions: d.suggested_actions,
  reply,
  needs_human_review: d.needs_human_review,
  error: d.error || null
}}];
